'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Each core domain''s score at the start of the period and now, drawn as a dumbbell, sorted by the biggest fall first.",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "background": "transparent",
  "params": [
    {
      "name": "evergreen",
      "expr": "pbiColor(0)"
    },
    {
      "name": "emerald",
      "expr": "pbiColor(1)"
    },
    {
      "name": "sage",
      "value": "#DCE8E0"
    },
    {
      "name": "amber",
      "expr": "pbiColor(3)"
    },
    {
      "name": "red",
      "expr": "pbiColor(4)"
    },
    {
      "name": "ink",
      "expr": "pbiColor(0)"
    },
    {
      "name": "muted",
      "expr": "pbiColor(6)"
    },
    {
      "name": "line",
      "expr": "pbiColor(8)"
    },
    {
      "name": "surface",
      "value": "#FFFFFF"
    },
    {
      "name": "cream",
      "value": "#F7F6F2"
    },
    {
      "name": "goodFill",
      "value": "#DDF0E8"
    },
    {
      "name": "warnFill",
      "value": "#F5EAD6"
    },
    {
      "name": "badFill",
      "value": "#F3E0DA"
    },
    {
      "name": "title",
      "value": "WHAT MOVED OVER THE PERIOD"
    },
    {
      "name": "domainOrder",
      "value": [
        "stability",
        "incidents",
        "problems",
        "maturity",
        "architecture",
        "risk",
        "security",
        "resilience",
        "change",
        "estate",
        "governance",
        "delivery",
        "people",
        "cost",
        "operability"
      ]
    },
    {
      "name": "labelWidth",
      "value": 220
    },
    {
      "name": "valueWidth",
      "value": 140
    }
  ],
  "title": {
    "text": {
      "expr": "title"
    },
    "subtitle": {
      "expr": "[length(data(''dataset'')) ? (data(''dataset'')[0][''Scope Name''] === ''Estate'' ? ''Whole estate'' : data(''dataset'')[0][''Scope Name'']) + (data(''dataset'')[0].quarters ? '', over the last '' + data(''dataset'')[0].quarters + '' quarters'' : '''') : '''', ''Change in health score, 60 to 100. Up is better.'']"
    },
    "font": "JetBrains Mono, Consolas, monospace",
    "fontSize": 12.5,
    "fontWeight": 600,
    "color": {
      "expr": "muted"
    },
    "anchor": "start",
    "offset": 6,
    "subtitleFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "subtitleFontSize": 12,
    "subtitleColor": {
      "expr": "muted"
    },
    "subtitlePadding": 4
  },
  "transform": [
    {
      "calculate": "datum[''Score Delta over Period''] > 0 ? emerald : datum[''Score Delta over Period''] < 0 ? amber : muted",
      "as": "moveColour"
    },
    {
      "calculate": "(datum[''Score Delta over Period''] > 0 ? ''+'' + datum[''Score Delta over Period''] : datum[''Score Delta over Period''] < 0 ? ''−'' + abs(datum[''Score Delta over Period'']) : ''0'') + '' '' + (datum[''Score Delta over Period''] > 0 ? ''better'' : datum[''Score Delta over Period''] < 0 ? ''worse'' : ''held'')",
      "as": "moveLabel"
    },
    {
      "calculate": "max(60, datum[''Score Period Start''])",
      "as": "fromAt"
    },
    {
      "calculate": "max(60, datum[''Score''])",
      "as": "toAt"
    },
    {
      "calculate": "min(datum[''Score Period Start''], datum[''Score'']) < 60",
      "as": "clamped"
    },
    {
      "calculate": "max(datum.fromAt, datum.toAt)",
      "as": "rightEnd"
    },
    {
      "calculate": "min(datum.fromAt, datum.toAt)",
      "as": "leftEnd"
    },
    {
      "calculate": "datum.clamped ? datum[''DomainName''] + '' <60'' : datum[''DomainName'']",
      "as": "domainLabel"
    },
    {
      "calculate": "indexof(domainOrder, datum[''DomainKey'']) < 0 ? length(domainOrder) : indexof(domainOrder, datum[''DomainKey''])",
      "as": "domainRank"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "moveOrder"
        }
      ],
      "sort": [
        {
          "field": "Score Delta over Period",
          "order": "ascending"
        },
        {
          "field": "domainRank",
          "order": "ascending"
        },
        {
          "field": "DomainName",
          "order": "ascending"
        }
      ]
    }
  ],
  "encoding": {
    "x": {
      "type": "quantitative",
      "scale": {
        "domain": [
          60,
          100
        ],
        "nice": false,
        "zero": false,
        "clamp": true,
        "range": [
          {
            "expr": "labelWidth"
          },
          {
            "expr": "max(labelWidth + 60, width - valueWidth)"
          }
        ]
      },
      "axis": {
        "title": "Domain score, 60 to 100",
        "titlePadding": 10,
        "values": [
          60,
          70,
          80,
          90,
          100
        ],
        "grid": false
      }
    },
    "y": {
      "field": "DomainName",
      "type": "nominal",
      "sort": {
        "field": "moveOrder",
        "op": "min",
        "order": "ascending"
      },
      "scale": {
        "paddingInner": 0.2,
        "paddingOuter": 0.2,
        "range": [
          22,
          {
            "expr": "max(22, height)"
          }
        ]
      },
      "axis": null
    },
    "tooltip": [
      {
        "field": "DomainName",
        "title": "Domain"
      },
      {
        "field": "Score Period Start",
        "title": "Start of period"
      },
      {
        "field": "Score",
        "title": "Now"
      },
      {
        "field": "moveLabel",
        "title": "Change"
      }
    ],
    "opacity": {
      "condition": {
        "test": "datum.__selected__ === ''off''",
        "value": 0.35
      },
      "value": 1
    }
  },
  "layer": [
    {
      "data": {
        "values": [
          {
            "at": 60
          },
          {
            "at": 80
          }
        ]
      },
      "mark": {
        "type": "rule",
        "y": 0,
        "y2": {
          "expr": "height"
        },
        "color": {
          "expr": "line"
        },
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "at",
          "type": "quantitative"
        },
        "y": null,
        "tooltip": null,
        "opacity": null
      }
    },
    {
      "data": {
        "values": [
          {
            "at": 60,
            "word": "WATCH"
          },
          {
            "at": 80,
            "word": "HEALTHY"
          }
        ]
      },
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "y": 0,
        "dx": 6,
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 11.5,
        "fontWeight": 600,
        "color": {
          "expr": "muted"
        }
      },
      "encoding": {
        "x": {
          "field": "at",
          "type": "quantitative"
        },
        "y": null,
        "text": {
          "field": "word"
        },
        "tooltip": null,
        "opacity": null
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": {
          "expr": "muted"
        },
        "strokeWidth": 1.5,
        "strokeOpacity": 0.6
      },
      "encoding": {
        "x": {
          "field": "fromAt"
        },
        "x2": {
          "field": "toAt"
        }
      }
    },
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 90,
        "fill": {
          "expr": "surface"
        },
        "stroke": {
          "expr": "muted"
        },
        "strokeWidth": 1.5
      },
      "encoding": {
        "x": {
          "field": "fromAt"
        },
        "shape": {
          "condition": {
            "test": "datum[''Score Period Start''] < 60",
            "value": "triangle-left"
          },
          "value": "circle"
        }
      }
    },
    {
      "params": [
        {
          "name": "__select__",
          "select": {
            "type": "point",
            "fields": [
              "DomainKey"
            ],
            "on": "click",
            "clear": "dblclick"
          }
        }
      ],
      "mark": {
        "type": "point",
        "filled": true,
        "size": 110,
        "stroke": {
          "expr": "surface"
        },
        "strokeWidth": 1.5
      },
      "encoding": {
        "x": {
          "field": "toAt"
        },
        "shape": {
          "condition": {
            "test": "datum[''Score''] < 60",
            "value": "triangle-left"
          },
          "value": "circle"
        },
        "color": {
          "field": "moveColour",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": 14,
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 12.5,
        "fontWeight": 600,
        "color": {
          "expr": "surface"
        },
        "stroke": {
          "expr": "surface"
        },
        "strokeWidth": 5,
        "strokeJoin": "round"
      },
      "encoding": {
        "x": {
          "field": "rightEnd"
        },
        "text": {
          "field": "moveLabel"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": 14,
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 12.5,
        "fontWeight": 600
      },
      "encoding": {
        "x": {
          "field": "rightEnd"
        },
        "text": {
          "field": "moveLabel"
        },
        "color": {
          "field": "moveColour",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "dx": -14,
        "fontSize": 13,
        "color": {
          "expr": "ink"
        }
      },
      "encoding": {
        "x": {
          "field": "leftEnd"
        },
        "text": {
          "field": "domainLabel"
        }
      }
    }
  ]
}'

'{
  "background": "transparent",
  "font": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
  "padding": 8,
  "view": {
